#include <stdio.h>

int main(void) {
    int limit = 0;
    int stop = 0;

    if (scanf("%d", &limit) != 1) {
        return 1;
    }
    if (scanf("%d", &stop) != 1) {
        return 1;
    }

    for (int i = 1; i <= limit; i++) {
        if (i == stop) {
            break;
        }
        printf("%d\n", i);
    }
    printf("收工喵\n");
    return 0;
}
